mapper.select:
SELECT `id` as id, `name` as name FROM `module_types` WHERE `status` = 1
AND `name` LIKE CONCAT("%", #{filter.searchText}, "%")
ORDER BY id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT `id` as id, `name` as name FROM `sections` WHERE `is_active` = 1
AND `name` LIKE CONCAT("%", #{filter.searchText}, "%")
ORDER BY id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT
(SELECT IFNULL(SUM(qty), 0) FROM inventories WHERE is_active = 1 AND location_id = locations.id
AND location_group_id = #{filter.warehouseId}
AND product_id = #{filter.productId}
) as totalQty,
`id` as id, `name` as name FROM `locations` WHERE `is_active` = 1
AND location_group_id = #{filter.warehouseId}
HAVING totalQty > 0
AND `name` LIKE CONCAT("%", #{filter.searchText}, "%")
ORDER BY id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT services.`id` as id, CONCAT(services.sku, ' - ', services.name) AS name, services.sku AS sku, services.sku AS upc, services.uom_id AS uomId, uoms.name AS uom, services.unit_price AS unitPrice, services.section_id AS sectionId, 2 AS type FROM `services` LEFT JOIN uoms ON services.uom_id = uoms.id WHERE services.is_active = 1
AND section_id = #{filter.sectionId}
AND `name` LIKE CONCAT("%", #{filter.searchText}, "%")
ORDER BY id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT `id` as id, `name` as name FROM `egroups` WHERE `is_active` = 1
AND (`name` LIKE CONCAT("%", #{filter.searchText}, "%"))
ORDER BY id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT `id` as id, `name` as name FROM `hr_todo_list_status` WHERE `is_active` = 1
AND (`name` LIKE CONCAT("%", #{filter.searchText}, "%"))
ORDER BY id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT `id` as id, `name` as name FROM `hr_todo_list_priorities` WHERE `is_active` = 1
AND (`name` LIKE CONCAT("%", #{filter.searchText}, "%"))
ORDER BY id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT `id` AS id, `name` AS name FROM `payment_types` WHERE `is_active` = 1
AND (`name` LIKE CONCAT("%", #{filter.searchText}, "%"))
ORDER BY id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT `id` AS id, `name` AS name FROM `classes` WHERE `is_active` = 1
AND (`name` LIKE CONCAT("%", #{filter.searchText}, "%"))
ORDER BY id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT `id` AS id, `name` AS name FROM pgroups -- WHERE pgroups.id = pgroups.parent_id
AND (`name` LIKE CONCAT("%", #{filter.searchText}, "%"))
ORDER BY id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT customers.`id` AS id, customers.`name` AS name, customers.photo AS photo, customers.payment_term_id AS paymentTermId, payment_terms.name AS paymentTermName FROM customers LEFT JOIN payment_terms ON customers.payment_term_id = payment_terms.id WHERE customers.`is_active` = 1
AND (customers.`name` LIKE CONCAT("%", #{filter.searchText}, "%"))
ORDER BY customers.id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT `id` AS id, `contact_name` AS name FROM customer_contacts WHERE `is_active` = 1 AND contact_type = 1
AND (`name` LIKE CONCAT("%", #{filter.searchText}, "%"))
AND customer_id = #{filter.organizationId}
ORDER BY id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT `id` AS id, `name` AS name FROM pgroups WHERE pgroups.is_active = 1
AND (`name` LIKE CONCAT("%", #{filter.searchText}, "%"))
ORDER BY id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT `id` as id, `name` as name, `code` as sku, `barcode` as upc FROM `products`
LEFT JOIN product_pgroups ON product_pgroups.product_id = products.id
WHERE `is_active` = 1
AND ( `name` LIKE CONCAT("%", #{filter.searchText}, "%") OR `code` LIKE CONCAT("%", #{filter.searchText}, "%") OR `barcode` LIKE CONCAT("%", #{filter.searchText}, "%") )
AND product_pgroups.pgroup_id = #{filter.groupId}
ORDER BY id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT `id` as id, `name` as name, `color` as color FROM `price_request_priorities` WHERE `is_active` = 1
AND (`name` LIKE CONCAT("%", #{filter.searchText}, "%"))
ORDER BY id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT `id` as id, `name` as name FROM `price_request_percentages` WHERE `is_active` = 1
AND (`name` LIKE CONCAT("%", #{filter.searchText}, "%"))
ORDER BY id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT vendors.id as id, vendors.name as name, vendors.work_telephone as code FROM vendors
INNER JOIN vendor_vgroups ON vendor_vgroups.vendor_id = vendors.id INNER JOIN vgroups ON vgroups.id = vendor_vgroups.vgroup_id
WHERE vendors.is_active = 1
AND (`name` LIKE CONCAT("%", #{filter.searchText}, "%"))
AND vgroups.`vendor_type_id` = #{filter.type}
ORDER BY id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT `id` as id, `name` as name FROM `price_request_vendors` WHERE `is_active` = 1
AND (`name` LIKE CONCAT("%", #{filter.searchText}, "%"))
ORDER BY ordering ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT uoms.id, uoms.name, uoms.abbr, 1 AS `conversion` FROM uoms LEFT JOIN products ON products.price_uom_id = uoms.id WHERE products.id = #{filter.productId}
UNION
SELECT uoms.id, uoms.name, uoms.abbr, (SELECT value FROM uom_conversions WHERE is_active = 1 AND from_uom_id = products.price_uom_id AND to_uom_id = uoms.id LIMIT 1) AS `conversion` FROM uoms LEFT JOIN products ON products.price_uom_id IS NOT NULL WHERE uoms.id IN (SELECT to_uom_id FROM uom_conversions WHERE is_active = 1 AND from_uom_id = products.price_uom_id) AND products.id = #{filter.productId} ORDER BY `conversion` ASC
LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT `id` as id, `name` as name FROM `delivery_status` WHERE `is_active` = 1
AND (`name` LIKE CONCAT("%", #{filter.searchText}, "%"))
ORDER BY id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT `id` as id, `name` as name FROM `landed_cost_types` WHERE `is_active` = 1
AND (`name` LIKE CONCAT("%", #{filter.searchText}, "%"))
ORDER BY id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT `id` as id, `name` as name, `vat_percent` as percent FROM `vat_settings` WHERE `is_active` = 1
AND type = #{filter.type}
AND (`name` LIKE CONCAT("%", #{filter.searchText}, "%"))
ORDER BY id ASC
LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT payment_terms.`id` as id, payment_terms.`name` as name, payment_types.id as typeId, payment_types.name as typeName FROM `payment_terms` LEFT JOIN payment_types ON payment_terms.payment_type_id = payment_types.id WHERE payment_terms.`is_active` = 1
AND (`name` LIKE CONCAT("%", #{filter.searchText}, "%"))
ORDER BY id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT `id` as id, `name` as name FROM `pgroups` WHERE `is_active` = 1
AND (`name` LIKE CONCAT("%", #{filter.searchText}, "%"))
ORDER BY id DESC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT `id` as id, `name` as name FROM `departments` WHERE `is_active` = 1
AND name LIKE CONCAT("%", #{filter.searchText}, "%")
AND telegram_group_id IS NULL
AND id = #{filter.id}
ORDER BY id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT id AS id, contact_name AS name FROM `vendor_contacts` WHERE is_active = 1
AND (`contact_name` LIKE CONCAT("%", #{filter.searchText}, "%"))
AND vendor_id = #{filter.vendorId}
ORDER BY id ASC
LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT request_stocks.id AS id, request_stocks.code AS code FROM request_stocks WHERE status >= 0 AND is_approve = 1
AND company_id = #{filter.companyId}
ORDER BY
${filter.orderBy}
request_stocks.id ASC
LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT products.id AS productId, products.name AS productName, products.barcode AS upc, products.code AS sku, products.price_uom_id AS uomId, uoms.name AS uomName, uoms.abbr AS uomAbbr,
IFNULL(((SELECT SUM(total_qty) FROM ${filter.warehouseId}_group_totals WHERE product_id = products.id) - (SELECT SUM(total_order) FROM ${filter.warehouseId}_group_totals WHERE product_id = products.id)),0) AS qtyInStock,
products.is_expired_date AS isExpiredDate, products.unit_cost AS unitCost, products.unit_cost AS estimateCost, products.description AS note FROM products LEFT JOIN uoms ON uoms.id = products.price_uom_id WHERE products.is_active = 1 AND products.company_id = 1
AND products.id = #{filter.productId}
AND products.code = #{filter.sku}
AND products.barcode = #{filter.upc}
LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT l.id AS locationId, l.name AS locationName, lg.id AS warehouseId, lg.name AS warehouseName, IFNULL(( SELECT SUM(qty) FROM inventories i INNER JOIN products p ON i.product_id = p.id WHERE i.is_active = 1 AND p.is_active = 1 AND p.id = #{filter.productId}
AND i.`date` <= #{filter.dateTo}
AND i.location_group_id = #{filter.warehouseId}
AND i.location_id = l.id ), 0) AS endingQty, IFNULL(( SELECT SUM(total_order) FROM inventory_totals WHERE inventory_totals.product_id = #{filter.productId} ), 0) AS orderQty FROM locations l INNER JOIN location_groups lg ON lg.id = l.location_group_id INNER JOIN user_locations ul ON ul.location_id = l.id INNER JOIN inventories i ON i.location_id = l.id INNER JOIN inventory_totals ON inventory_totals.product_id = #{filter.productId} WHERE ul.user_id = #{userId} AND l.is_active = 1 GROUP BY l.id HAVING endingQty > 0
